{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large glycosylated polyketide with the highest Morgan similarity to the query, showed a CSF:plasma ratio of only 0.12 in monkeys and was classified as poor brain penetration, indicating that large glycosylated DNA-binding agents do not achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1, a complex polycyclic natural product, had a brain-to-blood ratio of about 0.02 in mice and was judged unable to cross the blood-brain barrier, supporting poor CNS access for structurally complex, polar/ionizable molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Digitoxin, a cardiac glycoside, showed a very low CSF/plasma ratio of 0.01-0.03 in dogs, demonstrating that glycosylated natural products can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emodin-8-O-β-D-glucoside, an anthraquinone glycoside, distributed into rat brain and its brain concentration was elevated by cerebral ischemia/reperfusion, providing some evidence that anthraquinone glycosides can access CNS under barrier disruption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is doxorubicin, an anthracycline glycoside with a basic amine, very low passive permeability, and high efflux liability. The most transferable experimental evidence (mithramycin, DX-52-1, digitoxin) consistently shows poor CNS penetration for large glycosylated/ionizable natural products. The positive emodin glucoside result is less transferable and occurs under a specific ischemia/reperfusion disruption, so it does not outweigh the negative class evidence.",
  "evidence_gaps": [
    "No direct doxorubicin brain/plasma or CSF measurement under a defined disrupted-barrier condition is provided.",
    "The positive anthraquinone glycoside analogue (C07) lacks the basic amine and higher polarity of doxorubicin, limiting transferability.",
    "Efflux transporter substrate status is inferred from physicochemical properties rather than direct experimental transporter assays."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

